def extended_gcd(a, b):
    if a == 0:
        return b, 0, 1
    else:
        g, y, x = extended_gcd(b % a, a)
        return g, x - (b // a) * y, y

def solve_diophantine(p, q, target_det_val):
    g, x0, y0 = extended_gcd(q, p)
    if target_det_val % g != 0:
        return None
    a = x0 * (target_det_val // g)
    c = -y0 * (target_det_val // g)
